    for i in range(n):
        for j in range(n):
            if grid[i][j] < grid[start_i][start_j]:
                start_i, start_j = i, j

    path = [grid[start_i][start_j]]
    i, j = start_i, start_j

    for _ in range(k - 1):
        best_i = best_j = None
        best_val = None
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
