def minPath(grid, k):
    n = len(grid)

    # Locate the cell with minimum value (guaranteed unique values 1..n*n, so this is 1)
    start_i = start_j = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] < grid[start_i][start_j]:
                start_i, start_j = i, j

    path = [grid[start_i][start_j]]
    i, j = start_i, start_j

    for _ in range(k - 1):
        best_i = best_j = None
        best_val = None
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                v = grid[ni][nj]
                if best_val is None or v < best_val:
                    best_val = v
                    best_i, best_j = ni, nj
        path.append(best_val)
        i, j = best_i, best_j

    return path

